        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(
            Action<IServiceProvider, HttpClient>? client,
            Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = (_, c) => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IPlatformV2Api, PlatformV2Api>("OpenSkin.Client.Api.IPlatformV2Api", client));
            builders.Add(_services.AddHttpClient<IPlatformV2AutomationApi, PlatformV2AutomationApi>("OpenSkin.Client.Api.IPlatformV2AutomationApi", client));
            builders.Add(_services.AddHttpClient<IPlatformV2MarketAnalyticsApi, PlatformV2MarketAnalyticsApi>("OpenSkin.Client.Api.IPlatformV2MarketAnalyticsApi", client));
            builders.Add(_services.AddHttpClient<IPlatformV2MediaApi, PlatformV2MediaApi>("OpenSkin.Client.Api.IPlatformV2MediaApi", client));
            builders.Add(_services.AddHttpClient<IPlatformV2PricingApi, PlatformV2PricingApi>("OpenSkin.Client.Api.IPlatformV2PricingApi", client));
            builders.Add(_services.AddHttpClient<IPlatformV2ProfilesApi, PlatformV2ProfilesApi>("OpenSkin.Client.Api.IPlatformV2ProfilesApi", client));
            builders.Add(_services.AddHttpClient<IPlatformV2WebhooksApi, PlatformV2WebhooksApi>("OpenSkin.Client.Api.IPlatformV2WebhooksApi", client));

            foreach (IHttpClientBuilder instance in builders)
            {
                bool suppressDefault = false;
                OnAddApiHttpClientBuilder(instance, builder, ref suppressDefault);
                if (!suppressDefault)
                    builder?.Invoke(instance);
            }

            HttpClientsAdded = true;

            return this;
        }

